insert into public.companies(ticker,name,segment,size_tier,is_seed,is_hero,markets,exchange,country) values ($q$BYIT$q$,$q$Bytes Technology Group$q$,null,null,true,false,array[$q$LSE$q$]::text[],null,$q$GB$q$) on conflict (ticker) do update set is_seed=true, segment=excluded.segment, size_tier=excluded.size_tier, is_hero=excluded.is_hero, markets=case when cardinality(excluded.markets)>0 then excluded.markets else public.companies.markets end, exchange=coalesce(excluded.exchange, public.companies.exchange), country=coalesce(excluded.country, public.companies.country);
insert into public.companies(name,entity_type) select v.n,v.t from (values ($q$Adobe$q$,$q$public_company$q$),($q$Alphabet$q$,$q$public_company$q$),($q$Amazon$q$,$q$public_company$q$),($q$BeyondTrust$q$,$q$private_company$q$),($q$Biltron$q$,$q$private_company$q$),($q$Blaby District Council$q$,$q$institution$q$),($q$BlackRock$q$,$q$public_company$q$),($q$Camissa Asset Management$q$,$q$private_company$q$),($q$Check Point$q$,$q$public_company$q$),($q$Citrix$q$,$q$private_company$q$),($q$Cloud Bridge Technologies$q$,$q$private_company$q$),($q$Commvault$q$,$q$public_company$q$),($q$Coronation Fund Managers$q$,$q$public_company$q$),($q$CrowdStrike$q$,$q$public_company$q$),($q$Crown Commercial Services$q$,$q$institution$q$),($q$Darktrace$q$,$q$private_company$q$),($q$Dell$q$,$q$public_company$q$),($q$Home Office$q$,$q$institution$q$),($q$M&G Investments$q$,$q$public_company$q$),($q$Microsoft$q$,$q$public_company$q$),($q$Mimecast$q$,$q$private_company$q$),($q$NHS$q$,$q$institution$q$),($q$National Express$q$,$q$organization$q$),($q$Oracle$q$,$q$public_company$q$),($q$Palo Alto$q$,$q$public_company$q$),($q$Public Investment Corporation$q$,$q$institution$q$),($q$Recorded Future$q$,$q$private_company$q$),($q$Rubrik$q$,$q$public_company$q$),($q$SecurityHQ$q$,$q$private_company$q$),($q$ServiceNow$q$,$q$public_company$q$),($q$Sophos$q$,$q$private_company$q$),($q$Tanium$q$,$q$private_company$q$),($q$VMware$q$,$q$public_company$q$),($q$Vanguard Group$q$,$q$private_company$q$),($q$West Yorkshire Fire and Rescue Service$q$,$q$institution$q$),($q$Wiz$q$,$q$private_company$q$),($q$Zscaler$q$,$q$public_company$q$)) v(n,t) where not exists (select 1 from public.companies c where lower(c.name)=lower(v.n));
create temp table _q(i int primary key, t text) on commit drop;
insert into _q values (1,$q$A large percentage of our supply chain is with Microsoft, which has a ‘carbon negative’ date of 2030.$q$),(2,$q$Biltron (Pty) Ltd 18,262,478 7.73$q$),(3,$q$BlackRock 13,732,017 5.81$q$),(4,$q$Camissa Asset Management 36,845,706 15.59$q$),(5,$q$Coronation Fund Managers 67,159,310 28.41$q$),(6,$q$Following the acquisition of a 25.1% interest in Cloud Bridge Technologies in April 2023, in accordance with IAS 28 Investments in Associates and Joint Ventures we account for the Group’s share of its profit/loss.$q$),(7,$q$Group companies made purchases from the associate of £6.7 million (2025: £4.9 million) and sales to the associate of £0.2 million (2025: £0.1 million) during the year with a trade payable balance of £0.9 million (2025: £0.1 million) at the year end.$q$),(8,$q$However, its emissions intensity decreased by 9% in the past year, with AWS, Adobe and Palo Alto also making energy intensity reductions.$q$),(9,$q$In early 2025, National Express partnered with Bytes to move from an on-premises VMware environment to a cloud-based infrastructure on Amazon Web Services (AWS).$q$),(10,$q$Long-standing relationships between our non‑executive directors and the industry, which includes material vendors and partners, including Microsoft, which again this year gave a presentation to the Board.$q$),(11,$q$M&G Investments 7,166,647 3.03$q$),(12,$q$Microsoft has always been our biggest and most important vendor, and remained so this year.$q$),(13,$q$Microsoft is our largest supplier and formed 59% of our emissions in 2025/26.$q$),(14,$q$Microsoft relationship strength, with 68% of the Group’s GII and 50% of GP generated from sales of Microsoft products and associated service solutions, this continues to be a very important partnership for both sides.$q$),(15,$q$Oracle NetSuite implementation (new accounting system at Bytes)$q$),(16,$q$Our approved supplier status under the main public sector framework agreement with Crown Commercial Services (RM6098 Technology Products & Associated Services 2 (TePAS 2)) to 7 October 2027, which covers over half of the viability period, and taking into account of our long history of successfully retaining our position at previous renewal dates$q$),(17,$q$Our partners include Microsoft, AWS, Palo Alto, Check Point, Mimecast, Adobe, Darktrace, SecurityHQ, Commvault, ServiceNow, Wiz, Recorded Future, CrowdStrike, Zscaler and Google$q$),(18,$q$Our partners include Microsoft, AWS, VMware, Dell, Adobe, Sophos, Citrix, Mimecast, Rubrik, ServiceNow, BeyondTrust, Tanium and Zscaler$q$),(19,$q$Public Investment Corporation (PIC) 11,510,744 4.87$q$),(20,$q$The Group has a 25.1% interest in Cloud Bridge Technologies Limited, a company with a principal place of business in the United Kingdom.$q$),(21,$q$The Phoenix Protect active response managed service was the ideal fit.$q$),(22,$q$This is largely because our suppliers, such as Microsoft, Adobe and AWS, reduced their emissions intensity.$q$),(23,$q$Vanguard Group 9,909,131 4.19$q$),(24,$q$We are one of Microsoft’s largest UK partners by revenue and work hand in hand with more than 100 other world-leading vendors that make or distribute software, hardware and other IT products.$q$),(25,$q$We did more business with established customers such as the Home Office and the NHS.$q$),(26,$q$We maintain excellent relationships with all our vendors, and have a particularly good relationship with Microsoft, which relies on us as a key partner in the UK.$q$),(27,$q$Working with Phoenix, the fire service embarked on an ambitious, multi-year digital transformation programme to modernise its systems, while also supporting people with accessibility needs.$q$);
